function mergeSort(nums) {
  if (nums.length <= 1) return nums;              // one value is already sorted
  const mid = Math.floor(nums.length / 2);
  const left = mergeSort(nums.slice(0, mid));     // sort each half...
  const right = mergeSort(nums.slice(mid));
  return merge(left, right);                      // ...then merge them
}

function merge(left, right) {
  const out = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) out.push(left[i++]);   // <= keeps equal values in order: stable
    else out.push(right[j++]);
  }
  while (i < left.length) out.push(left[i++]);
  while (j < right.length) out.push(right[j++]);
  return out;
}

int[] mergeSort(int[] nums) {
    if (nums.length <= 1) return nums;                         // one value is already sorted
    int mid = nums.length / 2;
    int[] left = mergeSort(Arrays.copyOfRange(nums, 0, mid));  // sort each half...
    int[] right = mergeSort(Arrays.copyOfRange(nums, mid, nums.length));
    return merge(left, right);                                 // ...then merge them
}

int[] merge(int[] left, int[] right) {
    int[] out = new int[left.length + right.length];
    int i = 0, j = 0, k = 0;
    while (i < left.length && j < right.length) {
        if (left[i] <= right[j]) out[k++] = left[i++];        // <= keeps equal values in order: stable
        else out[k++] = right[j++];
    }
    while (i < left.length) out[k++] = left[i++];
    while (j < right.length) out[k++] = right[j++];
    return out;
}

vector<int> merge(const vector<int>& left, const vector<int>& right) {
    vector<int> out;
    size_t i = 0, j = 0;
    while (i < left.size() && j < right.size()) {
        if (left[i] <= right[j]) out.push_back(left[i++]);    // <= keeps equal values in order: stable
        else out.push_back(right[j++]);
    }
    while (i < left.size()) out.push_back(left[i++]);
    while (j < right.size()) out.push_back(right[j++]);
    return out;
}

vector<int> mergeSort(vector<int> nums) {
    if (nums.size() <= 1) return nums;                        // one value is already sorted
    size_t mid = nums.size() / 2;
    vector<int> left = mergeSort(vector<int>(nums.begin(), nums.begin() + mid));   // sort each half...
    vector<int> right = mergeSort(vector<int>(nums.begin() + mid, nums.end()));
    return merge(left, right);                                // ...then merge them
}
